import React, { useState, useEffect } from "react";
import "../styles/CreateArticlesAdmin.css";

function CreateArticlePage() {
  const [mode, setMode] = useState("article"); // article або poll
  const [channels, setChannels] = useState([]);

  // --- Дані для статті ---
  const [articleData, setArticleData] = useState({
    title: "",
    slug: "",
    content: "",
    excerpt: "",
    status: "draft",
    type: "standard",
    category: "sport",
    is_premium: false,
    image: null,
  });

  // --- Дані для опитування ---
  const [pollData, setPollData] = useState({
    question: "",
    channel: "",
    choices: ["", "", ""],
  });

  const token = localStorage.getItem("token");

  useEffect(() => {
    // Завантажуємо канали для вибору
    fetch("http://127.0.0.1:8000/api/channels/")
      .then((res) => res.json())
      .then((data) => setChannels(data))
      .catch((err) => console.error("Помилка при завантаженні каналів:", err));
  }, []);

  // --- Обробка зміни у статті ---
  const handleArticleChange = (e) => {
    const { name, value, type, checked, files } = e.target;
    if (type === "checkbox") {
      setArticleData({ ...articleData, [name]: checked });
    } else if (type === "file") {
      setArticleData({ ...articleData, [name]: files[0] });
    } else {
      setArticleData({ ...articleData, [name]: value });
    }
  };

  // --- Обробка зміни у опитуванні ---
  const handlePollChange = (e) => {
    const { name, value } = e.target;
    setPollData({ ...pollData, [name]: value });
  };

  const handleChoiceChange = (index, value) => {
    const newChoices = [...pollData.choices];
    newChoices[index] = value;
    setPollData({ ...pollData, choices: newChoices });
  };

  // --- Відправка статті ---
  const handleSubmitArticle = async (e) => {
    e.preventDefault();
    const data = new FormData();
    Object.entries(articleData).forEach(([key, value]) => data.append(key, value));

    try {
      const res = await fetch("http://127.0.0.1:8000/api/articles/", {
        method: "POST",
        headers: { Authorization: `Bearer ${token}` },
        body: data,
      });
      if (res.ok) {
        alert("✅ Статтю створено!");
        window.location.href = "/";
      } else {
        const err = await res.json();
        alert(`Помилка: ${JSON.stringify(err)}`);
      }
    } catch (error) {
      console.error("Помилка:", error);
    }
  };

  // --- Відправка опитування ---
  const handleSubmitPoll = async (e) => {
    e.preventDefault();
    const payload = {
      question: pollData.question,
      channel: pollData.channel,
      choices: pollData.choices.filter((c) => c.trim() !== "").map((text) => ({ text })),
    };

    try {
      const res = await fetch("http://127.0.0.1:8000/api/polls/", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify(payload),
      });

      if (res.ok) {
        alert("✅ Опитування створено!");
        window.location.href = "/";
      } else {
        const err = await res.json();
        alert(`Помилка при створенні опитування: ${JSON.stringify(err)}`);
      }
    } catch (error) {
      console.error("Помилка запиту:", error);
    }
  };

  return (
    <div className="create-article-container">
      <h2 className="create-article-title">Створити контент</h2>

      <div style={{ marginBottom: "20px" }}>
        <label>Тип контенту: </label>
        <select value={mode} onChange={(e) => setMode(e.target.value)}>
          <option value="article">📰 Стаття</option>
          <option value="poll">📊 Опитування</option>
        </select>
      </div>

      {mode === "article" ? (
        // --- Форма створення статті ---
        <form onSubmit={handleSubmitArticle} encType="multipart/form-data">
          <input
            type="text"
            name="title"
            placeholder="Заголовок"
            value={articleData.title}
            onChange={handleArticleChange}
            required
          />
          <input
            type="text"
            name="slug"
            placeholder="Slug"
            value={articleData.slug}
            onChange={handleArticleChange}
            required
          />
          <textarea
            name="content"
            placeholder="Основний текст"
            value={articleData.content}
            onChange={handleArticleChange}
            required
          />
          <textarea
            name="excerpt"
            placeholder="Короткий опис"
            value={articleData.excerpt}
            onChange={handleArticleChange}
          />
          <button type="submit" className="create-article-button">
            Створити статтю
          </button>
        </form>
      ) : (
        // --- Форма створення опитування ---
        <form onSubmit={handleSubmitPoll}>
          <input
            type="text"
            name="question"
            placeholder="Питання"
            value={pollData.question}
            onChange={handlePollChange}
            required
          />

          <label>Канал:</label>
          <select name="channel" value={pollData.channel} onChange={handlePollChange} required>
            <option value="">-- Виберіть канал --</option>
            {channels.map((ch) => (
              <option key={ch.id} value={ch.id}>
                {ch.name}
              </option>
            ))}
          </select>

          <h4>Варіанти відповідей:</h4>
          {pollData.choices.map((choice, index) => (
            <input
              key={index}
              type="text"
              placeholder={`Варіант ${index + 1}`}
              value={choice}
              onChange={(e) => handleChoiceChange(index, e.target.value)}
              required
            />
          ))}

          <button type="submit" className="create-article-button">
            Створити опитування
          </button>
        </form>
      )}
    </div>
  );
}

export default CreateArticlePage;
